extension Parser. Lookahead {
  mutating func consume<SpecSet: TokenSpecSet>(anySequence: SpecSet.Type) -> Int {
    var count = 0
    while consume(ifAnyIn: SpecSet. self) != nil {
      count += 1
    }
    return count
  }
}

